from common import Bank
B = Bank('127.', 1201, own='cte_124.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

H("871.d.1.A",3,"A student who wants to haul grain for a summer job writes down a goal, the steps and dates, then tracks his hours and reviews the results. He is:","planning, proposing, conducting and evaluating an occupational experience",["skipping the plan","only talking about it","avoiding evaluation"],"A work experience is planned and evaluated.")
H("871.d.1.A",4,"The final step in managing a supervised occupational experience is to:","evaluate the results and decide what to improve",["delete the records","avoid feedback","start another job without review"],"Evaluation closes the loop.")
H("871.d.1.B",3,"A student logs the miles driven, fuel purchased and hours worked on his trucking project each day. This shows proper:","record-keeping skills",["storage skills","guessing skills","scheduling errors"],"Accurate records support projects.")
H("871.d.1.B",4,"Accurate fuel receipts in a trucking project record help the student to:","calculate cost per mile and prove expenses",["avoid taxes","hide spending","skip tracking"],"Records support cost analysis.")
H("871.d.1.C",3,"A student builds his own spreadsheet with columns for each delivery run's date, load and mileage. He is using:","a customized record-keeping system for his experience",["a generic template only","no system","a coworker's lunch list"],"Customized systems fit the project.")
H("871.d.1.C",4,"A customized record system is most useful when it:","captures the specific data the project needs",["records unrelated things","has no dates","is never updated"],"Fit the system to the need.")
H("871.d.1.D",3,"A student who leads a youth safety campaign about railroad crossings at his school is taking part in:","a youth leadership opportunity",["a payroll audit","a paint project","a maintenance repair"],"Leadership builds a well-rounded experience.")
H("871.d.1.D",4,"Serving as an officer in a student transportation club mainly helps a student to:","develop leadership, communication and organizational skills",["avoid responsibility","reduce teamwork","skip meetings"],"Offices build leadership.")
H("871.d.1.E",3,"A student plans a delivery-van project by listing tasks, a timeline and expected costs of fuel, insurance and tolls. He is developing:","a work plan and budget",["a menu","a vacation list","a floor plan"],"Plans include tasks and costs.")
H("871.d.1.E",4,"A budget for an occupational experience should compare:","planned costs with expected income",["colors with sizes","names with dates","tools with weather"],"Budgets balance costs and income.")
H("871.d.2.A",3,"A student learns that in some countries drivers sit on the right and traffic moves on the left, while in the United States it moves on the right. This is a:","difference between international cultures' transportation systems",["similarity in all nations","mistake in a map","rule for pilots only"],"Cultural differences affect transport.")
H("871.d.2.A",4,"Both Tokyo and Houston rely on commuter rail, buses and highways. This is:","a similarity in transportation across different cultures",["a difference in all nations","a rare exception","a map error"],"Similar needs lead to similar systems.")
H("871.d.2.B",3,"A freight company ships electronics to Europe, produce to Asia and machinery to South America. This shows:","the variety of world markets",["a single local market","no trade","a ban on shipping"],"Markets differ around the world.")
H("871.d.2.B",4,"Exporting goods to a foreign market requires understanding the local:","customs, regulations and demand",["weather forecast only","team uniforms","menu prices"],"Markets differ by rules and demand.")
H("871.d.2.C",3,"A shipper learns that labels in another country must be in a different language and that cultural holidays affect delivery dates. These are:","marketing factors that impact other cultures",["accounting errors","engine parts","road signs"],"Language and holidays matter.")
H("871.d.2.C",4,"A company that ignores local customs when advertising a delivery service in a new country may:","offend customers and lose business",["gain every customer","avoid all risk","reduce its costs only"],"Cultural awareness supports marketing.")
H("871.d.3.A",3,"A new dispatcher learns that 'freight' means goods being moved and 'logistics' means planning their movement. She is:","learning terms associated with the transportation industries",["avoiding vocabulary","guessing words","skipping training"],"Know the terms.")
H("871.d.3.A",4,"In shipping, a 'bill of lading' is:","a document that lists the cargo and serves as a receipt",["a driver's lunch order","a type of truck engine","a road sign"],"A bill of lading documents cargo.")
H("871.d.3.B",3,"Grocery stores stay stocked, workers get to jobs and emergency supplies arrive quickly because of transportation. This shows the:","scope and effect of the transportation industry on society",["limited use of trucks","lack of any role","small economic role"],"Transportation touches everything.")
H("871.d.3.B",4,"If a major port closed for two weeks, the most likely effect would be:","delays and shortages in many industries",["lower prices everywhere","no change","faster delivery"],"Supply chains depend on ports.")
H("871.d.3.C",3,"The development of the transcontinental railroad, interstate highways and containerized shipping are examples of:","significant historical developments in transportation",["fictional events","minor changes","unrelated hobbies"],"History shaped transport.")
H("871.d.3.C",4,"Which current development is changing delivery services today?","use of electric and autonomous vehicles and real-time tracking",["horse-drawn carts","telegraph orders","paper maps only"],"Technology drives change.")
H("871.d.3.D",3,"Engineers testing drone deliveries and hydrogen-powered trucks are exploring:","potential future development of transportation systems",["old methods","past events only","unrelated fields"],"Prototypes show future directions.")
H("871.d.3.D",4,"A possible future change that could reduce urban congestion is:","wider use of shared autonomous shuttles and improved transit",["banning all roads","removing all traffic lights randomly","increasing parking only"],"Shared mobility cuts congestion.")
H("871.d.3.E",3,"A shipping company uses GPS tracking and automated sorting to deliver packages and now ships to buyers in many countries. This shows how:","emerging technologies and globalization affect transportation",["technology has no effect","globalization reduces trade","tracking slows shipping"],"Technology and globalization reshape transport.")
H("871.d.3.E",4,"Globalization has increased demand for:","container shipping, air cargo and efficient ports",["fewer shipments","slower delivery","local deliveries only"],"Global trade needs freight capacity.")
H("871.d.3.F",3,"A city debates whether to spend on new bike lanes or road widening, each with trade-offs for safety, cost and traffic. This is comparing:","issues affecting transportation such as safety, cost and efficiency",["unrelated topics","only colors","only weather"],"Compare issues and trade-offs.")
H("871.d.3.F",4,"A factor that raises costs for trucking companies and that they must weigh is:","fuel prices and driver shortages",["the color of trucks","lunch menus","school mascots"],"Costs and labor affect operations.")
H("871.d.4.A",3,"A fleet manager sets a budget, schedules drivers, tracks maintenance and supervises staff. These are:","common business management principles",["random acts","personal chores","hobbies"],"Planning, organizing, staffing and controlling.")
H("871.d.4.A",4,"The management function of controlling means:","comparing performance to goals and correcting problems",["setting no goals","ignoring results","hiring only"],"Controlling monitors results.")
H("871.d.4.B",3,"A dispatcher takes a leadership workshop and volunteers to mentor new drivers. She is:","taking an opportunity for leadership development and personal growth",["avoiding growth","ignoring training","quitting"],"Training and mentoring build leaders.")
H("871.d.4.B",4,"Which activity best builds leadership skills in a transportation career?","leading a safety committee",["working alone silently","skipping meetings","avoiding feedback"],"Committees build leadership.")
H("871.d.4.C",3,"A club president uses an agenda, takes votes and lets each member speak in turn. She is:","demonstrating democratic principles in running an effective meeting",["dominating the meeting","ignoring members","ending debate instantly"],"Order and fairness define a meeting.")
H("871.d.4.C",4,"In parliamentary procedure, a motion is made, seconded, discussed and then:","voted on by the members",["ignored","tossed out","delayed forever"],"Motions are decided by vote.")
H("871.d.4.D",3,"A new driver joins a crew that has strong cooperation and trust, and the group finishes loads faster. This describes positive:","team dynamics",["isolation","competition only","misunderstanding"],"Team dynamics are how members work together.")
H("871.d.4.D",4,"A team that has unclear roles and conflicting goals will most likely experience:","slow progress and frustration",["perfect cooperation","faster results","clear expectations"],"Unclear roles hurt teams.")
H("871.d.4.E",3,"A regional bus company announces that its mission is to provide safe, reliable and affordable transit and sets a goal of 98 percent on-time arrivals. This is:","developing organizational vision, mission and goals",["setting no direction","ignoring customers","a random slogan"],"Organizations define vision, mission and goals.")
H("871.d.4.E",4,"A mission statement tells employees:","the organization's purpose and what it does",["the weather forecast","the lunch menu","the exact route of one truck"],"Mission describes purpose.")
H("871.d.5.A",3,"A Texas port ships cotton and electronics overseas and receives tires and furniture in return because regions have different resources and strengths. This explains a reason for:","world trade and globalization",["isolation","local-only business","trade bans"],"Countries trade for goods they lack.")
H("871.d.5.A",4,"Which is a reason nations trade with each other?","different resources, costs and production strengths",["identical products everywhere","no demand","lack of ports"],"Specialization drives trade.")
H("871.d.5.B",3,"A state debates funding a new highway bypass, with lawmakers, businesses and residents lobbying. This shows the:","political impact of transportation",["absence of politics","no public interest","random events"],"Transportation decisions are political.")
H("871.d.5.B",4,"Transportation policy often becomes political because:","funding choices affect jobs, communities and the economy",["roads cost nothing","nobody uses roads","laws never change"],"Policy affects many groups.")
H("871.d.5.C",3,"A trucking company reviews federal hours-of-service rules and updates driver schedules so no driver exceeds the limit. This is:","reviewing regulations and evaluating their impact on operations",["ignoring laws","breaking rules","avoiding paperwork"],"Know and apply regulations.")
H("871.d.5.C",4,"A major law that shapes safety in trucking is the requirement that drivers:","rest between shifts under hours-of-service rules",["drive as long as they want","skip inspections","carry no records"],"HOS limits fatigue.")
H("871.d.5.D",3,"A fleet supervisor subscribes to a freight trade journal and reads about new emission rules before they take effect. This shows:","reading written material to stay current on industry issues",["ignoring news","avoiding research","skipping reading"],"Stay informed.")
H("871.d.5.D",4,"Reading trade publications helps transportation managers to:","anticipate changes in rules, costs and technology",["avoid decisions","ignore customers","skip training"],"Awareness supports planning.")
H("871.d.5.E",3,"A transit agency surveys riders and counts boardings at each stop before deciding which routes to cut. This is:","collecting public opinion and data to make informed decisions",["guessing","ignoring riders","avoiding data"],"Gather opinion and data.")
H("871.d.5.E",4,"Which data best supports a decision to add a bus route?","ridership counts and rider survey results for that area",["a single complaint","a rumor","the color of the bus"],"Data supports decisions.")
H("871.d.5.F",3,"A planner lists three ways to reduce congestion on a bridge, compares their costs and benefits and chooses the best. She is using:","critical-thinking skills to identify and organize alternatives",["random guessing","avoiding options","copying others"],"Compare alternatives.")
H("871.d.5.F",4,"After listing alternatives for a delivery delay, the next step is to:","evaluate each option against cost, time and risk",["pick one at random","ignore the list","wait for the problem to grow"],"Evaluate before choosing.")
H("871.d.5.G",3,"A city checks whether a contracted bus operator met the on-time standard in its agreement and reviews safety reports. This is:","evaluating performance and contract compliance of contractors",["ignoring the contract","paying without review","avoiding inspection"],"Contracts require review.")
